from PIL import Image
from collections import deque

def blobs(path, thresh=120, min_n=30, max_n=5000):
    im = Image.open(path)
    w, h = im.size
    px = im.load()
    seen = bytearray(w*h)
    def idx(x,y): return y*w+x
    out = []
    for y in range(h):
        for x in range(w):
            if seen[idx(x,y)]:
                continue
            p = px[x,y]
            if p[0]+p[1]+p[2] >= thresh:
                continue
            q = deque([(x,y)])
            seen[idx(x,y)] = 1
            comp = [(x,y)]
            while q:
                cx,cy = q.popleft()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny = cx+dx, cy+dy
                    if 0<=nx<w and 0<=ny<h and not seen[idx(nx,ny)]:
