        p=px[x,y]
        return p[0]+p[1]+p[2]
    grip = bytearray(w*h)
    def idx(x,y): return y*w+x
    q = deque()
    for x in range(w):
        for y in range(0, 15):
            if sm(x,y) < grip_sum and not grip[idx(x,y)]:
                grip[idx(x,y)] = 1
                q.append((x,y))
    while q:
        x,y = q.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<w and 0<=ny<h and not grip[idx(nx,ny)] and sm(nx,ny) < grip_sum:
                grip[idx(nx,ny)] = 1
                q.append((nx,ny))
    seen = bytearray(w*h)
    blobs = []
    for y in range(h):
        for x in range(w):
            if grip[idx(x,y)] or seen[idx(x,y)] or sm(x,y) >= dark_sum:
                continue
            q = deque([(x,y)])
            seen[idx(x,y)] = 1
