    while q:
        x,y = q.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<w and 0<=ny<h and not grip[idx(nx,ny)] and sm(nx,ny) < grip_sum:
                grip[idx(nx,ny)] = 1
                q.append((nx,ny))
    seen = bytearray(w*h)
    blobs = []
    for y in range(h):
        for x in range(w):
            if grip[idx(x,y)] or seen[idx(x,y)] or sm(x,y) >= dark_sum:
                continue
            q = deque([(x,y)])
            seen[idx(x,y)] = 1
            comp = [(x,y)]
            while q:
                cx,cy = q.popleft()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and not seen[idx(nx,ny)] and not grip[idx(nx,ny)] and sm(nx,ny) < dark_sum:
                        seen[idx(nx,ny)] = 1
                        q.append((nx,ny))
                        comp.append((nx,ny))
            if len(comp) < 40:
                continue
            # weighted centroid by darkness
            sw=sx=sy=0
            for (xx,yy) in comp:
                wt = max(1, dark_sum - sm(xx,yy))
                sw += wt; sx += xx*wt; sy += yy*wt
            xs=[c[0] for c in comp]; ys=[c[1] for c in comp]
            blobs.append({
                "n": len(comp),
                "cx": sx/sw, "cy": sy/sw,
                "minx": min(xs), "maxx": max(xs), "miny": min(ys), "maxy": max(ys)
            })
    return blobs

